// src/components/Dolar.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Line } from 'react-chartjs-2';

const Dolar = () => {
    const [data, setData] = useState([]);
    const [labels, setLabels] = useState([]);
    const apiBaseUrl = 'http://localhost:8000'; // Cambia esto a la URL donde está tu API

    const fetchPredictions = async () => {
        try {
            const response = await axios.get(`${apiBaseUrl}/prophet-predictions`);
            const { dates, values, predictions } = response.data;

            // Combina los datos actuales y las predicciones
            setData([...values, ...predictions]);
            setLabels([...dates, ...dates.slice(-10).map((_, i) => `Predicción ${i + 1}`)]);
        } catch (error) {
            console.error("Error al obtener predicciones:", error);
        }
    };

    useEffect(() => {
        fetchPredictions();
    }, []);

    const chartData = {
        labels: labels,
        datasets: [
            {
                label: 'Precio del Dólar (MXN)',
                data: data,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true,
            },
        ],
    };

    return (
        <div>
            <h1>Precio del Dólar en Tiempo Real</h1>
            {data.length > 0 ? (
                <Line data={chartData} />
            ) : (
                <p>Cargando datos...</p>
            )}
        </div>
    );
};

export default Dolar;
